create table if not exists public.wifi_packages (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, price_kes integer not null check (price_kes > 0), duration_minutes integer not null check (duration_minutes > 0), description text not null default '', is_active boolean not null default true, is_popular boolean not null default false, is_best_value boolean not null default false, display_order integer not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.payments (id uuid primary key default gen_random_uuid(), checkout_request_id text unique not null, phone text not null, package_id uuid references wifi_packages(id), amount_kes integer not null, mac_address text, status text not null check(status in ('PENDING','SUCCESS','FAILED')), mpesa_receipt_number text unique, raw_callback jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists public.wifi_sessions (id uuid primary key default gen_random_uuid(), payment_id uuid unique references payments(id), phone text not null, package_id uuid references wifi_packages(id), mac_address text, start_time timestamptz not null, expiry_time timestamptz not null, session_status text not null check(session_status in ('ACTIVE','EXPIRED','REVOKED','GATEWAY_FAILED')), gateway_reference text, created_at timestamptz not null default now());
alter table public.wifi_packages enable row level security; alter table public.payments enable row level security; alter table public.wifi_sessions enable row level security;
create policy "public reads active packages" on public.wifi_packages for select using (is_active = true);
